& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\Specialize.log";

$scripts = @(
	{
		Get-AppxPackage -Name 'Microsoft.Windows.Ai.Copilot.Provider' | Remove-AppxPackage;
	};
	{
		Remove-Item -LiteralPath "${env:USERPROFILE}\Desktop\Microsoft Edge.lnk" -ErrorAction 'SilentlyContinue' -Verbose;
		# Remove any other desktop shortcuts (apps may create them later via InstallApps)
		Get-ChildItem -Path "$env:USERPROFILE\Desktop", "$env:PUBLIC\Desktop" -Filter '*.lnk' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue;
	};
	{
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'LaunchTo' -Type 'DWord' -Value 1;
	};
	{
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'SearchboxTaskbarMode' -Type 'DWord' -Value 1;
	};
	{
		Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name 'VisualFXSetting' -Type 'DWord' -Value 1 -Force;
	};
	{
		New-Item -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Force;
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{5399e694-6ce5-4d6c-8fce-1d8870fdcba0}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{b4bfcc3a-db2c-424c-b029-7fe99a87c641}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{a8cdff1c-4878-43be-b5fd-f8091c1c60d0}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{374de290-123f-4565-9164-39c4925e467b}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{f874310e-b6b7-47dc-bc84-b9e6b38f5903}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{1cf1260c-4dd0-4ebb-811f-33c572699fde}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{f02c1a0d-be21-4350-88b0-7367fc96ef3c}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{3add1653-eb32-4cb0-bbd7-dfa0abb5acca}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{645ff040-5081-101b-9f08-00aa002f954e}' -Value 0 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{20d04fe0-3aea-1069-a2d8-08002b30309d}' -Value 0 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{59031a47-3f72-44a7-89c5-5595fe6b30ee}' -Value 0 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\ClassicStartMenu' -Name '{a0953c92-50dc-43bf-be83-3742fed03c9c}' -Value 1 -Type 'DWord';
		New-Item -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Force;
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{5399e694-6ce5-4d6c-8fce-1d8870fdcba0}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{b4bfcc3a-db2c-424c-b029-7fe99a87c641}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{a8cdff1c-4878-43be-b5fd-f8091c1c60d0}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{374de290-123f-4565-9164-39c4925e467b}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{f874310e-b6b7-47dc-bc84-b9e6b38f5903}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{1cf1260c-4dd0-4ebb-811f-33c572699fde}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{f02c1a0d-be21-4350-88b0-7367fc96ef3c}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{3add1653-eb32-4cb0-bbd7-dfa0abb5acca}' -Value 1 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{645ff040-5081-101b-9f08-00aa002f954e}' -Value 0 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{20d04fe0-3aea-1069-a2d8-08002b30309d}' -Value 0 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{59031a47-3f72-44a7-89c5-5595fe6b30ee}' -Value 0 -Type 'DWord';
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel' -Name '{a0953c92-50dc-43bf-be83-3742fed03c9c}' -Value 1 -Type 'DWord';
	};
	{
		Set-ItemProperty -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Start' -Name 'VisiblePlaces' -Value $( [convert]::FromBase64String('hghzUqpRQ0Kfeyd2WEZZ1LwkihQM1olCoIBu2buiSILO1TQtWvpDRYLyIubq93c8L7Nn496JVUO/zmHzexipNyAGC7BRfzJMqh40zFR/cxXFpbNChn30QoCkk/rKeoi1oAc/OArogEywWobbhF28TUqwvXRK+WhPi9ZDmAcdqLxEgXX+DQiuQovaNO2XtmOU') ) -Type 'Binary';
	};
	{
		# Create Screenshots folder
		New-Item -Path 'C:\Users\User\Pictures\Screenshots' -ItemType Directory -Force -ErrorAction SilentlyContinue;
	};
	{
		# Taskbar: combine only when full, active monitor only
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'Start_Layout' -Value 1 -Type DWord -Force;
		New-Item -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Force -ErrorAction SilentlyContinue | Out-Null;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Name 'AllAppsViewMode' -Value 1 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'TaskbarGlomLevel' -Value 1 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'MMTaskbarMode' -Value 2 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'MMTaskbarGlomLevel' -Value 1 -Type DWord -Force;
	};
	{
		# Accent color on title bars
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\DWM' -Name 'ColorPrevalence' -Value 1 -Type DWord -Force;
	};
	{
		# Show Task View button
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'ShowTaskViewButton' -Value 1 -Type DWord -Force;
	};
	{
		# Force Details view on all folders
		New-Item -Path 'Registry::HKCU\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags\AllFolders\Shell' -Force -ErrorAction SilentlyContinue;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags\AllFolders\Shell' -Name 'Mode' -Value 4 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags\AllFolders\Shell' -Name 'LogicalViewMode' -Value 1 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags\AllFolders\Shell' -Name 'FolderType' -Value 'NotSpecified' -Type String -Force;
	};
	{
		# Disable web search in taskbar
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'BingSearchEnabled' -Value 0 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'CortanaConsent' -Value 0 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'AllowSearchToUseLocation' -Value 0 -Type DWord -Force;
	};
	{
		# Hide Copilot button and Smart Clipboard
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'ShowCopilotButton' -Value 0 -Type DWord -Force;
		New-Item -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\SmartActionPlatform\SmartClipboard' -Force -ErrorAction SilentlyContinue;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\SmartActionPlatform\SmartClipboard' -Name 'Disabled' -Value 1 -Type DWord -Force;
		# Remove extra keyboard layouts - keep only Polish Programmers (0415:00000415)
		$langList = Get-WinUserLanguageList;
		foreach ($lang in $langList) {
			$extra = $lang.InputMethodTips | Where-Object { $_ -ne '0415:00000415' };
			foreach ($tip in $extra) { $lang.InputMethodTips.Remove($tip) | Out-Null; }
		}
		Set-WinUserLanguageList $langList -Force -ErrorAction SilentlyContinue;
		# Hide language bar
		New-Item -Path 'Registry::HKCU\Software\Microsoft\CTF\LangBar' -Force -ErrorAction SilentlyContinue | Out-Null;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\CTF\LangBar' -Name 'ShowStatus' -Value 3 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\CTF\LangBar' -Name 'Label' -Value 1 -Type DWord -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\CTF\LangBar' -Name 'ExtraIconsOnMinimized' -Value 0 -Type DWord -Force;
	};
	{
		# Audio enhancements off for all render devices
		Get-ChildItem -Path 'Registry::HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render' -ErrorAction SilentlyContinue | ForEach-Object {
			$fx = Join-Path $_.PSPath 'FxProperties';
			if (Test-Path $fx) { Set-ItemProperty -LiteralPath $fx -Name '{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},6' -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue; }
		};
	};
	{
		# Set WSL2 as default version
		wsl.exe --set-default-version 2;
	};
	{
		# Apply themeA (Captured Motion / Windows 11 built-in theme)
		Start-Process -FilePath 'C:\Windows\Resources\Themes\themeA.theme' -Wait;
	};


	{
		Get-Process -Name 'explorer' -ErrorAction 'SilentlyContinue' | Where-Object -FilterScript {
			$_.SessionId -eq ( Get-Process -Id $PID ).SessionId;
		} | Stop-Process -Force;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to configure this user account. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "$env:TEMP\UserOnce.log";

$scripts = @(
	{
		reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\WindowsCopilot" /v TurnOffWindowsCopilot /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Internet Explorer\LowRegistry\Audio\PolicyConfig\PropertyStore" /f;
	};
	{
		Remove-ItemProperty -LiteralPath 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run' -Name 'OneDriveSetup' -Force -ErrorAction 'Continue';
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\GameDVR" /v AppCaptureEnabled /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "HideFileExt" /t REG_DWORD /d 0 /f;
	};
	{
		if( [System.Environment]::OSVersion.Version.Build -lt 20000 ) {
			# Windows 10
			Set-ItemProperty -LiteralPath 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer' -Name 'EnableAutoTray' -Type 'DWord' -Value 0 -Force;
		} else {
			# Windows 11
			Register-ScheduledTask -TaskName 'ShowAllTrayIcons' -Xml $(
				Get-Content -LiteralPath "C:\Windows\Setup\Scripts\ShowAllTrayIcons.xml" -Raw;
			);
		}
	};
	{
		$names = @(
		  'ContentDeliveryAllowed';
		  'FeatureManagementEnabled';
		  'OEMPreInstalledAppsEnabled';
		  'PreInstalledAppsEnabled';
		  'PreInstalledAppsEverEnabled';
		  'SilentInstalledAppsEnabled';
		  'SoftLandingEnabled';
		  'SubscribedContentEnabled';
		  'SubscribedContent-310093Enabled';
		  'SubscribedContent-338387Enabled';
		  'SubscribedContent-338388Enabled';
		  'SubscribedContent-338389Enabled';
		  'SubscribedContent-338393Enabled';
		  'SubscribedContent-353694Enabled';
		  'SubscribedContent-353696Enabled';
		  'SubscribedContent-353698Enabled';
		  'SystemPaneSuggestionsEnabled';
		);
		
		foreach( $name in $names ) {
		  reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v $name /t REG_DWORD /d 0 /f;
		}
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v TaskbarAl /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\Explorer" /v DisableSearchBoxSuggestions /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced\TaskbarDeveloperSettings" /v TaskbarEndTask /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\DWM" /v ColorPrevalence /t REG_DWORD /d 1 /f;
	};
	{
		# Taskbar pins: File Explorer + Terminal + Edge (binary from configured session)
		$tbBytes = [System.Convert]::FromBase64String('');
		New-Item -Path 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' -Force -ErrorAction SilentlyContinue | Out-Null;
		Set-ItemProperty -LiteralPath 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' -Name 'Favorites' -Value $tbBytes -Type Binary -Force;
	};
	{
		# Start menu More Pins layout + List view for All Apps
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v Start_Layout /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Start" /v AllAppsViewMode /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -WindowStyle \""Normal\"" -ExecutionPolicy \""Unrestricted\"" -NoProfile -File \""C:\Windows\Setup\Scripts\UserOnce.ps1\""" /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to modify the default user’’s registry hive. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoLogonCount' -Type 'DWord' -Force -Value 0;
	};
	{
		cmd.exe /c "rmdir C:\Windows.old";
	};
	{
		Remove-Item -LiteralPath @(
		  'C:\Windows\Panther\unattend.xml';
		  'C:\Windows\Panther\unattend-original.xml';
		  'C:\Windows\Setup\Scripts\Wifi.xml';
		) -Force -ErrorAction 'SilentlyContinue' -Verbose;
	};
	{
		# Register elevated scheduled task for winget installs
		# Done here (not Specialize) because User account must exist for SID resolution
		$action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument '-WindowStyle Normal -ExecutionPolicy Unrestricted -NoProfile -File "C:\Windows\Setup\Scripts\InstallApps.ps1"';
		$trigger = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(10);
		$principal = New-ScheduledTaskPrincipal -UserId 'User' -LogonType Interactive -RunLevel Highest;
		$settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Hours 2) -StartWhenAvailable;
		Register-ScheduledTask -TaskName 'InstallApps' -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Force | Out-Null;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";

# Runs elevated via scheduled task at first logon - no UAC prompts $log = 'C:\Windows\Setup\Scripts\InstallApps.log' "$(Get-Date) Starting InstallApps" | Out-File $log Start-Sleep -Seconds 300 "$(Get-Date) Sleep done, updating winget sources" | Out-File $log -Append winget source update --disable-interactivity *>> $log "$(Get-Date) Source update done, installing apps" | Out-File $log -Append # NVIDIA driver first - ensures GPU is stable for the rest of the session winget install --id Greenshot.Greenshot --silent --accept-package-agreements --accept-source-agreements *>> $log # Override Greenshot ini after install (winget may reset it) $gsIniDest = "$env:APPDATA\Greenshot" New-Item -Path $gsIniDest -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null Copy-Item -Path 'C:\Windows\Setup\Scripts\Greenshot.ini' -Destination $gsIniDest -Force winget install --id WinDirStat.WinDirStat --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id Microsoft.PowerToys --scope machine --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id Git.Git --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id Notepad++.Notepad++ --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id 7zip.7zip --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id Microsoft.VisualStudioCode --scope machine --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id VideoLAN.VLC --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id Google.Chrome --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id Microsoft.PowerShell --silent --accept-package-agreements --accept-source-agreements *>> $log winget install --id REALiX.HWiNFO --silent --accept-package-agreements --accept-source-agreements *>> $log # Copy HWiNFO shortcut to ASCII path for reliable Start menu pinning $hwReg = [char]0x00ae $hwSrc = "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\HWiNFO$hwReg 64\HWiNFO$hwReg 64.lnk" $hwDst = "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\HWiNFO64.lnk" if (Test-Path $hwSrc) { Copy-Item $hwSrc $hwDst -Force } # Python 3 - direct install from python.org (winget --scope machine unreliable) "$(Get-Date) Installing Python 3" | Out-File $log -Append $py3exe = "$env:TEMP\python3-installer.exe" Invoke-WebRequest -Uri 'https://www.python.org/ftp/python/3.13.3/python-3.13.3-amd64.exe' -OutFile $py3exe -UseBasicParsing Start-Process $py3exe -ArgumentList '/quiet InstallAllUsers=1 PrependPath=1 Include_launcher=1 AssociateFiles=0' -Wait Remove-Item $py3exe -Force -ErrorAction SilentlyContinue "$(Get-Date) Python 3 done" | Out-File $log -Append # Python 2.7 (EOL, not in winget - install directly) "$(Get-Date) Installing Python 2.7" | Out-File $log -Append $py2msi = "$env:TEMP\python-2.7.18.amd64.msi" Invoke-WebRequest -Uri 'https://www.python.org/ftp/python/2.7.18/python-2.7.18.amd64.msi' -OutFile $py2msi -UseBasicParsing Start-Process msiexec.exe -ArgumentList "/i `"$py2msi`" /quiet /norestart TARGETDIR=C:\Python27 ADDLOCAL=ALL" -Wait # Create python2.exe so 'python2' works in terminal Copy-Item 'C:\Python27\python.exe' 'C:\Python27\python2.exe' -Force -ErrorAction SilentlyContinue # Add C:\Python27 to system PATH (after Python3 so 'python' still calls Python 3) $mp = [Environment]::GetEnvironmentVariable('PATH','Machine') if ($mp -notlike '*Python27*') { [Environment]::SetEnvironmentVariable('PATH', $mp + ';C:\Python27', 'Machine') } "$(Get-Date) Python 2.7 done" | Out-File $log -Append winget upgrade --all --silent --accept-package-agreements --accept-source-agreements *>> $log "$(Get-Date) All installs done" | Out-File $log -Append # Schedule a delayed Chrome shortcut cleanup (Chrome recreates shortcut after our cleanup) $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument '-WindowStyle Hidden -Command "Start-Sleep 60; Remove-Item -Path \"C:\\Users\\User\\Desktop\\Google Chrome.lnk\" -Force -ErrorAction SilentlyContinue; Remove-Item -Path \"C:\\Users\\Public\\Desktop\\Google Chrome.lnk\" -Force -ErrorAction SilentlyContinue; Unregister-ScheduledTask -TaskName ChromeShortcutCleanup -Confirm:$false"' $trigger = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(2) Register-ScheduledTask -TaskName 'ChromeShortcutCleanup' -Action $action -Trigger $trigger -RunLevel Highest -Force -ErrorAction SilentlyContinue | Out-Null # Wait for Chrome/VLC background post-install tasks to finish Start-Sleep -Seconds 20 # Remove desktop shortcuts created by installed apps $desktops = @( "C:\Users\User\Desktop", "$env:PUBLIC\Desktop", [System.Environment]::GetFolderPath('CommonDesktopDirectory') ) | Select-Object -Unique foreach ($d in $desktops) { Get-ChildItem -Path $d -Filter '*.lnk' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue } # Install OpenSSH Server (Feature-on-Demand) - done here post-logon where networking is up Add-WindowsCapability -Online -Name OpenSSH.Server~~~~0.0.1.0 -ErrorAction SilentlyContinue | Out-Null Start-Service sshd -ErrorAction SilentlyContinue Set-Service -Name sshd -StartupType Automatic -ErrorAction SilentlyContinue # sshd_config only exists after the service first starts; now set port 41 $sshdConf = 'C:\ProgramData\ssh\sshd_config' if (Test-Path $sshdConf) { (Get-Content $sshdConf) -replace '#?Port 22','Port 41' | Set-Content $sshdConf Restart-Service sshd -ErrorAction SilentlyContinue } New-NetFirewallRule -Name 'sshd-41' -DisplayName 'OpenSSH Server (port 41)' -Enabled True -Direction Inbound -Protocol TCP -Action Allow -LocalPort 41 -ErrorAction SilentlyContinue | Out-Null # Create .lnk shortcuts for Calculator, Notepad, Terminal with correct icons $wsh2 = New-Object -ComObject WScript.Shell $progDir = "$env:ProgramData\Microsoft\Windows\Start Menu\Programs" $expl = "$env:SystemRoot\explorer.exe" # Extract Calculator icon from package Assets (PNG-to-ICO conversion) $calcIco = $null try { $calcPkg = Get-AppxPackage -Name Microsoft.WindowsCalculator -ErrorAction SilentlyContinue if ($calcPkg) { $assets = Join-Path $calcPkg.InstallLocation 'Assets' # Get 32x32 Calculator icon PNG (targetsize-32 is already correct size, no downsampling needed) $png = Get-ChildItem $assets -Filter 'CalculatorAppList.targetsize-32.png' -ErrorAction SilentlyContinue | Select-Object -First 1 if (-not $png) { $png = Get-ChildItem $assets -Filter 'CalculatorAppList.scale-200.png' -ErrorAction SilentlyContinue | Select-Object -First 1 } if ($png -and $png.FullName) { Add-Type -AssemblyName System.Drawing $bmp = [System.Drawing.Bitmap]::new([string]$png.FullName) $ico = [System.Drawing.Icon]::FromHandle($bmp.GetHicon()) $calcIco = 'C:\Windows\Setup\Scripts\CalcIcon.ico' $fs = [System.IO.FileStream]::new([string]$calcIco, [System.IO.FileMode]::Create) $ico.Save($fs); $fs.Close(); $ico.Dispose(); $bmp.Dispose() } } } catch {} # Create Calculator.lnk shortcut $calcLnk = $wsh2.CreateShortcut("$progDir\Calculator.lnk") $calcLnk.TargetPath = $expl $calcLnk.Arguments = 'shell:AppsFolder\Microsoft.WindowsCalculator_8wekyb3d8bbwe!App' if ($calcIco -and (Test-Path $calcIco)) { $calcLnk.IconLocation = "$calcIco,0" } $calcLnk.Save()
# Extract Terminal icon from package Assets (same approach as Calculator) $termIco = $null try { # Try Get-AppxPackage first (reliable on fresh install after winget upgrade) $termPkg = Get-AppxPackage -Name Microsoft.WindowsTerminal -ErrorAction SilentlyContinue $termLoc = if ($termPkg -and (Test-Path (Join-Path $termPkg.InstallLocation 'Assets'))) { $termPkg.InstallLocation } else { # Fallback: find any Terminal version with Assets accessible $found = Get-ChildItem 'C:\Program Files\WindowsApps' -Filter 'Microsoft.WindowsTerminal_*_x64__8wekyb3d8bbwe' -ErrorAction SilentlyContinue | Where-Object { Test-Path (Join-Path $_.FullName 'Assets') } | Sort-Object LastWriteTime -Descending | Select-Object -First 1 if ($found) { $found.FullName } else { $null } } if ($termLoc) { $termAssets = Join-Path $termLoc 'Assets' $termPng = Get-ChildItem $termAssets -Filter 'Terminal_*targetsize-32*.png' -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch 'contrast|unplated' } | Select-Object -First 1 if (-not $termPng) { $termPng = Get-ChildItem $termAssets -Filter '*.png' -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'targetsize-32' -and $_.Name -notmatch 'contrast|unplated' } | Select-Object -First 1 } if (-not $termPng) { $termPng = Get-ChildItem $termAssets -Filter '*.png' -ErrorAction SilentlyContinue | Sort-Object Length -Descending | Select-Object -First 1 } if ($termPng -and $termPng.FullName) { Add-Type -AssemblyName System.Drawing $bmp = [System.Drawing.Bitmap]::new([string]$termPng.FullName) $ico = [System.Drawing.Icon]::FromHandle($bmp.GetHicon()) $termIco = 'C:\Windows\Setup\Scripts\TerminalIcon.ico' $fs = [System.IO.FileStream]::new([string]$termIco, [System.IO.FileMode]::Create) $ico.Save($fs); $fs.Close(); $ico.Dispose(); $bmp.Dispose() } } } catch {}
# Extract Notepad icon from current package exe to stable .ico path $notepadIco = $null try { $notepadPkg = Get-AppxPackage -Name Microsoft.WindowsNotepad -ErrorAction SilentlyContinue if ($notepadPkg) { $notepadExe = Join-Path (Join-Path $notepadPkg.InstallLocation 'Notepad') 'Notepad.exe' if (Test-Path $notepadExe) { Add-Type -AssemblyName System.Drawing $ico = [System.Drawing.Icon]::ExtractAssociatedIcon([string]$notepadExe) $notepadIco = 'C:\Windows\Setup\Scripts\NotepadIcon.ico' $fs = [System.IO.FileStream]::new([string]$notepadIco, [System.IO.FileMode]::Create) $ico.Save($fs); $fs.Close(); $ico.Dispose() } } } catch {}
@{ 'Notepad.lnk' = @{ A='shell:AppsFolder\Microsoft.WindowsNotepad_8wekyb3d8bbwe!App'; P='Microsoft.WindowsNotepad'; E='Notepad.exe'; Sub='Notepad'; UseNotepadIco=$true } 'Terminal.lnk' = @{ A='shell:AppsFolder\Microsoft.WindowsTerminal_8wekyb3d8bbwe!App'; P='Microsoft.WindowsTerminal'; E='wt.exe'; UseTermIco=$true } }.GetEnumerator() | ForEach-Object { try { $info = $_.Value $lnk = $wsh2.CreateShortcut("$progDir\$($_.Key)") $lnk.TargetPath = $expl $lnk.Arguments = $info.A $pkg = Get-AppxPackage -Name $info.P -ErrorAction SilentlyContinue if ($pkg) { if ($info.ContainsKey('UseTermIco') -and $termIco -and (Test-Path $termIco)) { $lnk.IconLocation = "$termIco,0" } elseif ($info.ContainsKey('UseNotepadIco') -and $notepadIco -and (Test-Path $notepadIco)) { $lnk.IconLocation = "$notepadIco,0" } elseif ($info.ContainsKey('I')) { $lnk.IconLocation = "$($info.I),0" } else { $subDir = if ($info.ContainsKey('Sub')) { $info.Sub } else { '' } $exePath = if ($subDir) { Join-Path (Join-Path $pkg.InstallLocation $subDir) $info.E } else { Join-Path $pkg.InstallLocation $info.E } if (-not (Test-Path $exePath)) { $found = Get-ChildItem $pkg.InstallLocation -Filter $info.E -ErrorAction SilentlyContinue | Select-Object -First 1 if ($found) { $exePath = $found.FullName } } if ($exePath -and (Test-Path $exePath)) { $lnk.IconLocation = "$exePath,0" } } } $lnk.Save() } catch {} } # Re-apply Start menu pins now that apps are installed & 'C:\Windows\Setup\Scripts\SetStartPins.ps1' Start-Sleep -Seconds 3 # Fallback: create Screenshots folder if UserOnce didn't New-Item -Path 'C:\Users\User\Pictures\Screenshots' -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null # Fallback: set search box to icon only Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'SearchboxTaskbarMode' -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue # Fallback: apply themeA if still on aero (UserOnce may have crashed before reaching theme step) $currentTheme = (Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes' -ErrorAction SilentlyContinue).CurrentTheme if ($currentTheme -notlike '*themeA*') { Start-Process 'C:\Windows\Resources\Themes\themeA.theme' Start-Sleep -Seconds 5 } # Re-apply taskbar settings (UserOnce may have been reset by theme application) Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'TaskbarGlomLevel' -Value 1 -Type DWord -Force Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'MMTaskbarMode' -Value 2 -Type DWord -Force Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'MMTaskbarGlomLevel' -Value 1 -Type DWord -Force Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'Start_Layout' -Value 1 -Type DWord -Force New-Item -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Force -ErrorAction SilentlyContinue | Out-Null Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Name 'AllAppsViewMode' -Value 1 -Type DWord -Force # Configure Windows Terminal settings $terminalSettings = @{ '$help' = 'https://aka.ms/terminal-documentation' '$schema' = 'https://aka.ms/terminal-profiles-schema' 'defaultProfile' = '{574e775e-4f2a-5b96-ac1e-a2962a402336}' 'copyOnSelect' = $true 'copyFormatting' = 'none' 'useAcrylicInTabRow' = $true 'initialCols' = 80 'initialRows' = 20 'newTabMenu' = @(@{ 'type' = 'remainingProfiles' }) 'profiles' = @{ 'defaults' = @{ 'useAtlasEngine' = $true } } 'schemes' = @() } $termDir = "$env:LOCALAPPDATA\Packages\Microsoft.WindowsTerminal_8wekyb3d8bbwe\LocalState" New-Item -Path $termDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null $terminalSettings | ConvertTo-Json -Depth 10 | Set-Content "$termDir\settings.json" -Encoding UTF8 # Set Windows Terminal as default terminal app New-Item -Path 'HKCU:\Console\%%Startup' -Force -ErrorAction SilentlyContinue | Out-Null Set-ItemProperty -Path 'HKCU:\Console\%%Startup' -Name 'DelegationConsole' -Value '{2EACA947-7F5F-4CFA-BA87-8F7FBEEFBE69}' -Type String -Force Set-ItemProperty -Path 'HKCU:\Console\%%Startup' -Name 'DelegationTerminal' -Value '{E12CFF52-A866-4C77-9A90-F570A7AA2C6B}' -Type String -Force # Set VisiblePlaces BEFORE deleting start2.bin so it gets encoded into regenerated start2.bin $vpBytes = [System.Convert]::FromBase64String('hghzUqpRQ0Kfeyd2WEZZ1LwkihQM1olCoIBu2buiSILO1TQtWvpDRYLyIubq93c8L7Nn496JVUO/zmHzexipNyAGC7BRfzJMqh40zFR/cxXFpbNChn30QoCkk/rKeoi1oAc/OArogEywWobbhF28TUqwvXRK+WhPi9ZDmAcdqLxEgXX+DQiuQovaNO2XtmOU') New-Item -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Force -ErrorAction SilentlyContinue | Out-Null Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Name 'VisiblePlaces' -Value $vpBytes -Type Binary -ErrorAction SilentlyContinue # NOW delete start2.bin - StartMenuExperienceHost regenerates it with VisiblePlaces already set $start2 = "$env:LOCALAPPDATA\Packages\Microsoft.Windows.StartMenuExperienceHost_cw5n1h2txyewy\LocalState\start2.bin" if (Test-Path $start2) { Remove-Item $start2 -Force -ErrorAction SilentlyContinue } Stop-Process -Name 'StartMenuExperienceHost' -Force -ErrorAction SilentlyContinue Start-Sleep -Seconds 30 # Restart Explorer so Start menu refreshes with resolved pins Get-Process explorer | Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId } | Stop-Process -Force Start-Sleep -Seconds 15 # Safety net: re-apply VisiblePlaces after Explorer restart $vpBytes2 = [System.Convert]::FromBase64String('hghzUqpRQ0Kfeyd2WEZZ1LwkihQM1olCoIBu2buiSILO1TQtWvpDRYLyIubq93c8L7Nn496JVUO/zmHzexipNyAGC7BRfzJMqh40zFR/cxXFpbNChn30QoCkk/rKeoi1oAc/OArogEywWobbhF28TUqwvXRK+WhPi9ZDmAcdqLxEgXX+DQiuQovaNO2XtmOU') New-Item -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Force -ErrorAction SilentlyContinue | Out-Null Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Start' -Name 'VisiblePlaces' -Value $vpBytes2 -Type Binary -ErrorAction SilentlyContinue # Re-apply Taskband binary after Explorer restart (Explorer restart resets taskbar to defaults) $tbBytes2 = [System.Convert]::FromBase64String('hghzUqpRQ0Kfeyd2WEZZ1LwkihQM1olCoIBu2buiSILO1TQtWvpDRYLyIubq93c8L7Nn496JVUO/zmHzexipNyAGC7BRfzJMqh40zFR/cxXFpbNChn30QoCkk/rKeoi1oAc/OArogEywWobbhF28TUqwvXRK+WhPi9ZDmAcdqLxEgXX+DQiuQovaNO2XtmOU') New-Item -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' -Force -ErrorAction SilentlyContinue | Out-Null Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' -Name 'Favorites' -Value $tbBytes2 -Type Binary -Force -ErrorAction SilentlyContinue # Delayed Chrome shortcut cleanup (Chrome recreates shortcut after install) Start-Sleep -Seconds 30 Remove-Item -Path 'C:\Users\User\Desktop\Google Chrome.lnk' -Force -ErrorAction SilentlyContinue Remove-Item -Path 'C:\Users\Public\Desktop\Google Chrome.lnk' -Force -ErrorAction SilentlyContinue Unregister-ScheduledTask -TaskName 'InstallApps' -Confirm:$false -ErrorAction SilentlyContinue
